//! Error types for the SCID decoder and encoder.
//!
//! Two levels, by design:
//! - [`ScidError`]: error at the FILE level (invalid magic, unsupported
//!   version, I/O). Fatal: the entire database cannot be opened.
//! - [`GameDecodeError`]: error at the level of A SINGLE GAME (unknown
//!   encoding, corrupted move stream, illegal move once resolved by the
//!   vendored chess engine, [`crate::chess`]...). Not fatal: the caller
//!   can skip the game and keep importing the rest of the database.
//!
//! Writing adds two more, symmetric error types: [`GameEncodeError`]
//! (the write-side mirror of [`GameDecodeError`]) and [`AddGameError`]
//! (everything that can go wrong while adding one game to a database
//! being written — parsing, encoding, or a format size limit).

use std::fmt;
use std::io;

/// Fatal error: the database (the file triplet) cannot be opened.
#[derive(Debug)]
pub enum ScidError {
    /// Read/open error on one of the three files.
    Io(io::Error),
    /// The magic number at the start of the file does not match the expected format.
    BadMagic,
    /// Unsupported version number (si4: only version 400 is
    /// currently written/read by the reference implementation).
    BadVersion(u16),
    /// File truncated or of a size inconsistent with the expected format.
    Truncated(&'static str),
}

impl fmt::Display for ScidError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Io(e)           => write!(f, "erreur de lecture : {e}"),
            Self::BadMagic        => write!(f, "nombre magique invalide (fichier non SCID ?)"),
            Self::BadVersion(v)   => write!(f, "version de format non supportée : {v}"),
            Self::Truncated(what) => write!(f, "fichier tronqué ou corrompu : {what}"),
        }
    }
}

impl std::error::Error for ScidError {}

impl From<io::Error> for ScidError {
    fn from(e: io::Error) -> Self {
        Self::Io(e)
    }
}

/// Non-fatal error: a single game could not be decoded.
///
/// Deliberately terse for end-user display (a caller importing a whole
/// database typically just counts how many games were skipped); the
/// `Debug`/`Display` detail is meant for diagnostics.
#[derive(Debug)]
pub enum GameDecodeError {
    /// The game has a non-standard starting position (START flag or custom
    /// FEN). Kept for `Display`/exhaustiveness; no longer returned by
    /// [`crate::game_blob`], which decodes these positions normally.
    NonStandardStart,
    /// The game contains at least one variation (sub-line). Kept for
    /// `Display`/exhaustiveness; no longer returned by [`crate::game_blob`],
    /// which decodes nested variations normally.
    ContainsVariations,
    /// The game contains a null move ("null move"), which has no equivalent
    /// in [`crate::chess`].
    NullMove,
    /// A byte of the move stream does not match any known control token
    /// nor a decodable move (corrupted stream or unrecognized format).
    BadMoveStream(&'static str),
    /// The decoded move (origin/destination/promotion) does not match any
    /// legal move generated by [`crate::chess`] in the current position — a
    /// sign either of file corruption or of a decoding bug to fix.
    IllegalMove { ply: usize },
    /// The game blob in the `.sg4`/`.sg5` has a length inconsistent
    /// with what the `IndexEntry` indicates (offset/length out of the file's bounds).
    BadOffset,
}

impl fmt::Display for GameDecodeError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::NonStandardStart      => write!(f, "position de départ non standard (variante d'erreur non utilisée)"),
            Self::ContainsVariations    => write!(f, "partie avec variantes (variante d'erreur non utilisée)"),
            Self::NullMove              => write!(f, "coup nul rencontré (non représentable)"),
            Self::BadMoveStream(what)   => write!(f, "flux de coups corrompu : {what}"),
            Self::IllegalMove { ply }   => write!(f, "coup illégal au demi-coup {ply}"),
            Self::BadOffset             => write!(f, "offset/longueur de partie hors bornes du fichier .sg"),
        }
    }
}

impl std::error::Error for GameDecodeError {}

/// Error while encoding a [`crate::chess::game_tree::GameTree`] back into a
/// `.sg4`/`.sg5` move-stream blob — the write-side mirror of
/// [`GameDecodeError`].
///
/// Should never occur for a tree built by legal play (
/// [`crate::chess::pgn::import_pgn`], or the [`crate::chess::game`]/
/// [`crate::chess::history`] API): every variant here reflects an
/// internal inconsistency between the tree and the position it claims to
/// represent, not a normal, expected failure — a well-formed tree always
/// encodes successfully.
#[derive(Debug)]
pub enum GameEncodeError {
    /// The move's origin square holds no piece known to the SCID
    /// piece-index bookkeeping table (see [`crate::game_blob`]'s module
    /// doc, "Piece-index renumbering on capture") — a mismatch between
    /// the tree's recorded moves and the position they claim to reach.
    UnknownPieceIndex,
    /// The move's origin/destination geometry does not match any pattern
    /// this piece type's SCID encoding can represent (e.g. a "bishop
    /// move" that is not actually diagonal).
    UnencodableMove,
    /// The game's custom starting position (non-standard FEN) has more
    /// than 16 pieces of one color — the hard limit the `[Square; 16]`
    /// piece-index table can represent (see [`crate::game_blob`]'s module
    /// doc, "Non-standard starting positions"; the exact same limit
    /// [`crate::GameDecodeError::BadMoveStream`] enforces on read for the
    /// same reason). Never occurs for the standard starting position.
    TooManyPieces,
}

impl fmt::Display for GameEncodeError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::UnknownPieceIndex => write!(f, "case de départ du coup introuvable dans la table d'indices de pièces"),
            Self::UnencodableMove => write!(f, "forme de coup non représentable dans l'encodage SCID"),
            Self::TooManyPieces => write!(f, "plus de 16 pièces d'un camp dans la position de départ personnalisée"),
        }
    }
}

impl std::error::Error for GameEncodeError {}

/// Error returned when a game's blob, or the games file it is appended
/// to, exceeds a size limit inherent to the si4/si5 on-disk format — see
/// [`crate::scid_common::LoadedDatabase::add_game`]. Not gated behind
/// `chess-extras`: this is pure storage bookkeeping, independent of PGN
/// parsing.
#[derive(Debug)]
pub enum StorageLimitError {
    /// The move-stream blob is larger than the 17-bit length field of an
    /// `IndexEntry` can represent (131071 bytes) — astronomically larger
    /// than any real game (even a several-thousand-move game blob is only
    /// a few KB), but checked rather than silently truncated.
    GameTooLarge,
    /// The games file has grown beyond what the target format's `IndexEntry`
    /// offset field can address: 32 bits (~4 GB) for si4, 47 bits (~140 TB)
    /// for si5 — checked rather than silently corrupted. si4's bound is a
    /// real historical limitation (the reason si5 exists at all), not a
    /// purely theoretical one like si5's.
    DatabaseTooLarge,
}

impl fmt::Display for StorageLimitError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::GameTooLarge => write!(f, "partie trop volumineuse pour le format (limite 131071 octets)"),
            Self::DatabaseTooLarge => write!(f, "fichier de parties trop volumineux pour le format"),
        }
    }
}

impl std::error::Error for StorageLimitError {}

/// Error while adding a game to, or updating a game in, a SCID database
/// being written.
///
/// Covers the whole pipeline of
/// [`crate::si4::database::Si4Database::add_game`]/`update_game` and their
/// si5 equivalents: the input PGN text could not be parsed, its move tree
/// could not be encoded, a size limit of the on-disk format was exceeded,
/// or (`update_game` only — `add_game` always appends a fresh game, so
/// this variant never applies to it) the targeted game does not exist. No
/// partial modification is made to the database on any of these errors.
#[derive(Debug)]
#[cfg(feature = "chess-extras")]
pub enum AddGameError {
    /// The input text could not be parsed as a PGN game (see
    /// [`crate::chess::pgn::PgnError`]).
    Pgn(crate::chess::pgn::PgnError),
    /// The parsed game's move tree could not be encoded (see
    /// [`GameEncodeError`]).
    Encode(GameEncodeError),
    /// A size limit of the on-disk format was exceeded (see
    /// [`StorageLimitError`]).
    Storage(StorageLimitError),
    /// `update_game` targeted a game index that does not exist. Never
    /// returned by `add_game`.
    NotFound,
}

#[cfg(feature = "chess-extras")]
impl fmt::Display for AddGameError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Pgn(e) => write!(f, "PGN invalide : {e}"),
            Self::Encode(e) => write!(f, "échec d'encodage de la partie : {e}"),
            Self::Storage(e) => write!(f, "{e}"),
            Self::NotFound => write!(f, "aucune partie à cet index"),
        }
    }
}

#[cfg(feature = "chess-extras")]
impl std::error::Error for AddGameError {}

#[cfg(feature = "chess-extras")]
impl From<crate::chess::pgn::PgnError> for AddGameError {
    fn from(e: crate::chess::pgn::PgnError) -> Self {
        Self::Pgn(e)
    }
}

#[cfg(feature = "chess-extras")]
impl From<GameEncodeError> for AddGameError {
    fn from(e: GameEncodeError) -> Self {
        Self::Encode(e)
    }
}

#[cfg(feature = "chess-extras")]
impl From<StorageLimitError> for AddGameError {
    fn from(e: StorageLimitError) -> Self {
        Self::Storage(e)
    }
}
